    ["Okay"] = "OK",
    ["Cancel"] = "Annuler",
    ["Skipping the step |cFFFFFF00%s|r will also cause the following steps to skip:\n|cFFFFFF00%s|r\nIf you wanted to just complete the step, |cffff0000cancel|r this dialog and right-click instead.\n"] = "Passer l'étape |cFFFFFF00%s|r entraînera aussi le passage des étapes suivantes :\n|cFFFFFF00%s|r\nSi vous vouliez simplement terminer l'étape, |cffff0000annulez|r ce dialogue et faites plutôt un clic droit.\n",
    ["Discord Server!"] = "Serveur Discord !",
    ["Connect with other players, get help, and stay updated!"] = "Échangez avec d'autres joueurs, obtenez de l'aide et restez informé !",
    ["Copy"] = "Copier",
    ["Close"] = "Fermer",
    ["Load Next Guide"] = "Charger le guide suivant",
