    -- Configuration section headers (WoWPro_Config.lua).
    ["Behavior"] = "Comportement",
    ["Button Display Options"] = "Options d'affichage des boutons",
    ["Window Layout"] = "Disposition de la fenêtre",
    ["Position & Anchor"] = "Position et ancrage",
    ["Window Sizing"] = "Taille de la fenêtre",
    ["Content Spacing"] = "Espacement du contenu",
    ["Appearance"] = "Apparence",
    ["Guide Behavior"] = "Comportement du guide",
    ["About"] = "À propos",
    ["What WoW-Pro Does"] = "Ce que fait WoW-Pro",
    ["Where To Start"] = "Par où commencer",
    ["Runtime Status"] = "État d'exécution",
    ["Stay Connected"] = "Rester connecté",
    ["Discord Invite"] = "Invitation Discord",
    ["Source Repository"] = "Dépôt source",
    ["Help"] = "Aide",
    ["Getting Started"] = "Pour commencer",
    ["Starting WoW-Pro"] = "Démarrer WoW-Pro",
    ["Exporting And Sharing"] = "Exporter et partager",
    ["Default is 0.5 seconds."] = "Par défaut : 0,5 seconde.",
    -- About tab, command list, and help paragraphs (WoWPro_Config.lua).
    ["WoW-Pro is a community-built addon collection that helps with questing, leveling, and guide-driven progression."] = "WoW-Pro est une collection d'addons créée par la communauté qui aide pour les quêtes, la montée de niveau et la progression guidée.",
    ["It has grown through years of player contributions, covering content from legacy expansions through current Retail."] = "Il s'est développé au fil des années grâce aux contributions des joueurs, couvrant les extensions passées jusqu'au Retail actuel.",
    ["New here: begin with Main and Guide Display to set automation, layout, and text style."] = "Nouveau : commencez par Général et Affichage du guide pour régler l'automatisation, la disposition et le style de texte.",
    ["Troubleshooting: open Main > Tools for logging and About > Commands for command shortcuts."] = "Dépannage : ouvrez Général > Outils pour les journaux et À propos > Commandes pour les raccourcis de commandes.",
    ["Use these links for announcements, support, and development updates."] = "Utilisez ces liens pour les annonces, l'assistance et les nouvelles de développement.",
    ["Tip: Include your guide name or ID and a short log snippet when asking for help in Discord."] = "Astuce : indiquez le nom ou l'ID de votre guide et un court extrait de journal lorsque vous demandez de l'aide sur Discord.",
    ["Use /wp or /wow-pro with the following commands:"] = "Utilisez /wp ou /wow-pro avec les commandes suivantes :",
    ["- where: print current map position and area details"] = "- where : afficher la position actuelle sur la carte et les détails de la zone",
    ["- reset: clear WoW-Pro saved runtime state"] = "- reset : effacer l'état d'exécution enregistré de WoW-Pro",
    ["- clear-log / log: clear or show the debug log"] = "- clear-log / log : effacer ou afficher le journal de débogage",
    ["- guide-bug / trade-bug: create focused bug reports"] = "- guide-bug / trade-bug : créer des rapports de bug ciblés",
    ["- devcoords / devzone / devmode: developer mapping helpers"] = "- devcoords / devzone / devmode : outils de cartographie pour développeurs",
    ["- flightids [dest]: inspect flight node IDs for your current map"] = "- flightids [dest] : inspecter les ID des nœuds de vol de votre carte actuelle",
    -- Getting Started and Troubleshooting bullets (WoWPro_Config.lua).
    ["Start here to select a guide and set your questing preferences."] = "Commencez ici : choisissez un guide et définissez vos préférences de quêtes.",
    ["- If steps do not advance, check Main > General automation and the Ranks page. Open Main > Tools to enable debugging and inspect the log."] = "- Si les étapes n'avancent pas, vérifiez l'automatisation dans Général > Général et la page Rangs. Ouvrez Général > Outils pour activer le débogage et consulter le journal.",
    ["- Use /wp log to inspect debug entries and /wp clear-log before reproducing issues."] = "- Utilisez /wp log pour inspecter les entrées de débogage et /wp clear-log avant de reproduire un problème.",
    ["- Use /wp reset if saved state becomes inconsistent after major patches."] = "- Utilisez /wp reset si l'état enregistré devient incohérent après une mise à jour majeure.",
    ["- If needed, share logs and guide ID in Discord for faster support."] = "- Si nécessaire, partagez les journaux et l'ID du guide sur Discord pour obtenir de l'aide plus rapidement.",
    -- Rank, automation, and legend help text (WoWPro_Config.lua).
    ["Ranks control how many optional steps are included in guides.\n1 = shortest route (core progression only), 2 = balanced route, 3 = fullest route (most optional content).\n\nPriority for this character is: Toon Rank first, then Global Rank as fallback."] = "Les rangs déterminent combien d'étapes facultatives sont incluses dans les guides.\n1 = trajet le plus court (progression principale uniquement), 2 = trajet équilibré, 3 = trajet le plus complet (un maximum de contenu facultatif).\n\nPriorité pour ce personnage : le rang du personnage d'abord, puis le rang global en secours.",
    ["Default rank for all characters and guides unless overridden.\n\nUse 1 for speed leveling, 2 for normal play, or 3 for completion-focused runs."] = "Rang par défaut pour tous les personnages et guides, sauf remplacement.\n\nUtilisez 1 pour une montée de niveau rapide, 2 pour un jeu normal, ou 3 pour des parties axées sur l'achèvement.",
    ["Character-specific override for this toon.\n\nIf set, this value is used instead of Global Rank for this character."] = "Remplacement spécifique à ce personnage.\n\nS'il est défini, cette valeur est utilisée à la place du rang global pour ce personnage.",
    ["Profile-level rank for this module's guide type.\n\nUse this when you want different strictness for %s than your default rank."] = "Rang au niveau du profil pour le type de guide de ce module.\n\nUtilisez ceci si vous voulez une rigueur différente pour %s que celle de votre rang par défaut.",
    ["Adjust the delay used while waiting for WoW API state updates. Increase this if steps complete too early; decrease it if updates feel sluggish."] = "Ajuste le délai d'attente des mises à jour d'état de l'API WoW. Augmentez-le si les étapes se terminent trop tôt ; diminuez-le si les mises à jour semblent lentes.",
    ["Action letters appear in each step and indicate what kind of step it is. Use this legend to quickly decode guide rows."] = "Des lettres d'action apparaissent dans chaque étape et indiquent son type. Utilisez cette légende pour décoder rapidement les lignes du guide.",
    -- Getting Started walkthrough steps (WoWPro_Config.lua).
    ["1) Click the Horn icon for the classic Guide List, or right-click the Options icon for the new Guide List. Choose a guide matching your level, campaign, or expansion."] = "1) Cliquez sur l'icône Corne pour la liste des guides classique, ou faites un clic droit sur l'icône Options pour la nouvelle liste. Choisissez un guide adapté à votre niveau, campagne ou extension.",
    ["2) Open Main > General for Auto Select, Auto Accept, Auto Turn-in, Quest Tracking, and Auto-Load Guide. Use Main > Guide Modifiers to choose optional content."] = "2) Ouvrez Général > Général pour la sélection auto, l'acceptation auto, la remise auto, le suivi des quêtes et le chargement auto. Utilisez Général > Modificateurs de guide pour choisir le contenu facultatif.",
    ["3) Open Guide Display > Window Layout to adjust Position & Anchor, Window Sizing, and Content Spacing. Use Appearance for backgrounds and Text Formatting for fonts and text size."] = "3) Ouvrez Affichage du guide > Disposition de la fenêtre pour régler Position et ancrage, Taille de la fenêtre et Espacement du contenu. Utilisez Apparence pour les arrière-plans et Formatage du texte pour les polices et la taille du texte.",
    ["4) Start playing. WoW-Pro will load the selected guide into the main frame and advance steps as quests and objectives update."] = "4) Jouez. WoW-Pro charge le guide sélectionné dans la fenêtre principale et avance les étapes au fil des quêtes et objectifs.",
    ["5) If a guide looks stuck or out of sync, use /wp reset to clear guide state and /wp log to inspect the debug log before reporting the issue."] = "5) Si un guide semble bloqué ou désynchronisé, utilisez /wp reset pour effacer l'état du guide et /wp log pour consulter le journal de débogage avant de signaler le problème.",
    -- Recorder walkthrough (WoWPro_Config.lua).
    ["Starting With The Recorder"] = "Débuter avec l'enregistreur",
    ["1) Enable WoWPro_Recorder in the AddOns list, then reload the UI if needed. When it is active, a recorder toolbar appears above the main WoW-Pro frame."] = "1) Activez WoWPro_Recorder dans la liste des addons, puis rechargez l'interface si nécessaire. Lorsqu'il est actif, une barre d'outils d'enregistreur apparaît au-dessus de la fenêtre principale de WoW-Pro.",
    ["2) Click New on the recorder toolbar to create a guide. Choose the guide type first, then fill in the guide fields such as Guide ID, zone, author, faction, and level range."] = "2) Cliquez sur Nouveau dans la barre d'outils de l'enregistreur pour créer un guide. Choisissez d'abord le type de guide, puis remplissez les champs comme l'ID du guide, la zone, l'auteur, la faction et la plage de niveaux.",
    ["3) Finish the New Guide dialog to register the guide. WoW-Pro will load that guide immediately so you can begin editing or recording steps into it."] = "3) Terminez la boîte de dialogue Nouveau guide pour enregistrer le guide. WoW-Pro charge immédiatement ce guide pour que vous puissiez commencer à le modifier ou à y enregistrer des étapes.",
    ["4) Click Record to capture questing progress while you play. Click Stop any time you want to pause before moving, testing, or editing steps manually."] = "4) Cliquez sur Enregistrer pour capturer la progression des quêtes pendant que vous jouez. Cliquez sur Arrêter à tout moment pour faire une pause avant de vous déplacer, de tester ou de modifier des étapes manuellement.",
    ["5) Use Open to load an existing guide for editing. Use Save to write the current recorder version to your saved guides so it can be reopened later."] = "5) Utilisez Ouvrir pour charger un guide existant à modifier. Utilisez Sauvegarder pour écrire la version actuelle de l'enregistreur dans vos guides enregistrés afin de pouvoir la rouvrir plus tard.",
    ["6) In Advanced mode, use Add to insert a step after the selected step, or use buttons such as Run, Flight, Portal, Note, and Delete to refine the route."] = "6) En mode avancé, utilisez Ajouter pour insérer une étape après l'étape sélectionnée, ou des boutons comme Courir, Vol, Portail, Note et Supprimer pour affiner l'itinéraire.",
    ["7) Use /wpr to toggle Basic or Advanced recorder mode. Use /wpr help to list recorder slash commands, and /wpr qdebug on or off if you need extra quest API logging while testing."] = "7) Utilisez /wpr pour basculer entre le mode enregistreur simple et avancé. Utilisez /wpr help pour lister les commandes slash de l'enregistreur, et /wpr qdebug on ou off si vous avez besoin de journaux d'API de quêtes supplémentaires pendant les tests.",
    ["8) After saving, reopen the guide with Open and run through a few steps to verify quest IDs, notes, and automatic completion behave the way you expect."] = "8) Après avoir sauvegardé, rouvrez le guide avec Ouvrir et parcourez quelques étapes pour vérifier que les ID de quête, les notes et l'achèvement automatique se comportent comme prévu.",
    -- Export and sharing steps (WoWPro_Config.lua).
    ["1) Click Save after recording or editing. The recorder opens a large text box containing the full Lua guide definition for the currently loaded guide."] = "1) Cliquez sur Sauvegarder après l'enregistrement ou la modification. L'enregistreur ouvre une grande zone de texte contenant la définition Lua complète du guide actuellement chargé.",
    ["2) Copy that text and paste it into a guide file if you want to move the guide into the addon source, share it with another author, or submit it for review."] = "2) Copiez ce texte et collez-le dans un fichier de guide si vous voulez intégrer le guide au code source de l'addon, le partager avec un autre auteur ou le soumettre pour relecture.",
    ["3) The recorder also keeps a saved copy in WoWPro_RecorderDB, so you can reload the guide later with Open even if you have not moved it into a permanent guide file yet."] = "3) L'enregistreur conserve aussi une copie dans WoWPro_RecorderDB, ce qui vous permet de recharger le guide plus tard avec Ouvrir même si vous ne l'avez pas encore déplacé dans un fichier de guide permanent.",
    ["4) For out-of-game backup or sharing, look in your WoW SavedVariables for WoWPro_Recorder.lua under WTF/Account/<account>/SavedVariables. That file stores the recorder guides saved on this installation."] = "4) Pour une sauvegarde ou un partage hors jeu, cherchez WoWPro_Recorder.lua dans vos SavedVariables WoW, sous WTF/Account/<account>/SavedVariables. Ce fichier contient les guides de l'enregistreur sauvegardés sur cette installation.",
    -- Broker popups (WoWPro_Broker.lua).
    ["Would you like to trash %s?"] = "Voulez-vous détruire %s ?",
    ["Please enter the quest ID to select and then click GO!"] = "Saisissez l'ID de la quête à sélectionner, puis cliquez sur GO !",
    ["Go!"] = "GO !",
    ["Never Mind"] = "Annuler",
    ["quest id #"] = "ID de quête #",
    -- First-run welcome dialogs (WoWPro_Broker.lua).
    ["Welcome to WoWPro. For this addon to function, you need to enable one of the following addons: |cffFF9900WoW-|r|cff46921APro|r Achievements, |cffFF9900WoW-|r|cff46921APro|r Dailies, |cffFF9900WoW-|r|cff46921APro|r Leveling, |cffFF9900WoW-|r|cff46921APro|r Professions, or |cffFF9900WoW-|r|cff46921APro|r WorldEvents."] = "Bienvenue dans WoWPro. Pour que cet addon fonctionne, vous devez activer l'un des addons suivants : |cffFF9900WoW-|r|cff46921APro|r Hauts faits, |cffFF9900WoW-|r|cff46921APro|r Quêtes journalières, |cffFF9900WoW-|r|cff46921APro|r Niveau, |cffFF9900WoW-|r|cff46921APro|r Métiers ou |cffFF9900WoW-|r|cff46921APro|r Événements mondiaux.",
    ["Welcome to WoWPro.\n\nFor this addon to function properly, you need to install either: |cffFF9900TomTom|r or |cffFF9900Carbonite|r to supply the arrow.\n\nWoW-Pro's guides won't have their full functionality without one of them!\n\nDownload it for free from www.wowinterface.com or www.curseforge.com."] = "Bienvenue dans WoWPro.\n\nPour que cet addon fonctionne correctement, vous devez installer |cffFF9900TomTom|r ou |cffFF9900Carbonite|r pour fournir la flèche.\n\nLes guides de WoW-Pro n'auront pas toutes leurs fonctionnalités sans l'un des deux !\n\nTéléchargez-le gratuitement sur www.wowinterface.com ou www.curseforge.com.",
    -- Step-problem report dialog (WoWPro_CurrentGuide.lua).
    ["WoWPro - Report Step Problem"] = "WoWPro - Signaler un problème d'étape",
    ["1. Copy the Discord invite below (Ctrl+C) and open it in your browser.\n2. Copy the details below and paste them into Discord, then describe what went wrong."] = "1. Copiez l'invitation Discord ci-dessous (Ctrl+C) et ouvrez-la dans votre navigateur.\n2. Copiez les détails ci-dessous, collez-les dans Discord, puis décrivez ce qui s'est mal passé.",
    ["Select details"] = "Sélectionner les détails",
    ["Select invite"] = "Sélectionner l'invitation",
    ["Faction: %s\nGuide: %s\nRank: %s (%s)"] = "Faction : %s\nGuide : %s\nRang : %s (%s)",
    -- Selector, nil-guide, error log, and step-action tooltips.
    ["Stop asking to switch to this guide.\nResetting the guide will re-enable asking to switch."] = "Ne plus demander à passer à ce guide.\nRéinitialiser le guide réactivera la demande de changement.",
    ["Would you like to switch to the guide for the quest you just accepted?"] = "Voulez-vous passer au guide de la quête que vous venez d'accepter ?",
    ["No Guide Loaded"] = "Aucun guide chargé",
    ["To select a guide, click the horn icon in the top bar"] = "Pour sélectionner un guide, cliquez sur l'icône Corne dans la barre supérieure",
    ["Select All and Copy the above error message to report this log. Hit ESC to close."] = "Sélectionnez tout et copiez le message d'erreur ci-dessus pour signaler ce journal. Appuyez sur ÉCHAP pour fermer.",
    ["No Combat"] = "Pas de combat",
    ["Loot Complete"] = "Butin complet",
    ["Chat"] = "Discussion",
