    -- Recorder step-editor descriptions, part 1.
    ["Check if this is a chat step."] = "Cochez s'il s'agit d'une étape de dialogue.",
    ["Check if this is a quest completion step NOT involving combat."] = "Cochez s'il s'agit d'une étape d'achèvement de quête SANS combat.",
    ["Check if this is an optional step."] = "Cochez s'il s'agit d'une étape facultative.",
    ["Check if this is an sticky step."] = "Cochez s'il s'agit d'une étape épinglée.",
    ["Check if this is an unsticky step."] = "Cochez s'il s'agit d'une étape non épinglée.",
    ["Choose the quest you'd like to base this step on:"] = "Choisissez la quête sur laquelle baser cette étape :",
    ["Are you sure you want to delete this step?\n"] = "Voulez-vous vraiment supprimer cette étape ?\n",
    ["Are you sure you want to delete this guide? This action cannot be undone.\n\n"] = "Voulez-vous vraiment supprimer ce guide ? Cette action est irréversible.\n\n",
    ["The step's type."] = "Le type de l'étape.",
    ["The main text for this step - often the quest name."] = "Le texte principal de cette étape – souvent le nom de la quête.",
    ["The main text for this step - often the quest title."] = "Le texte principal de cette étape – souvent le titre de la quête.",
    -- Recorder step-editor descriptions, part 2.
    ["Insert your current location and zone"] = "Insérer votre position et zone actuelles",
    ["Jump to a step index while staying in the editor."] = "Aller à l'index d'une étape sans quitter l'éditeur.",
    ["Open a numbered list of every step in the current guide."] = "Ouvre une liste numérotée de toutes les étapes du guide actuel.",
    ["Registers the guide to be used. Current guide will be lost unless saved."] = "Enregistre le guide pour utilisation. Le guide actuel sera perdu s'il n'est pas sauvegardé.",
    ["The guide's type determines what kind of events will be listened for."] = "Le type de guide détermine les événements écoutés.",
    ["The quest you choose will determine what values are loaded into the step editor."] = "La quête choisie détermine les valeurs chargées dans l'éditeur d'étape.",
    ["The rank of the step. If you are unsure, leave it as 1."] = "Le rang de l'étape. En cas de doute, laissez 1.",
    ["This step will be marked complete when you reach this level."] = "Cette étape sera marquée comme terminée lorsque vous atteindrez ce niveau.",
    ["The quest tied to this step. If this quest is complete, this step will be checked off."] = "La quête liée à cette étape. Si elle est terminée, l'étape sera cochée.",
    ["You need a zone tag if the coordinates lead to a point outside the guide's title zone."] = "Vous avez besoin d'un tag de zone si les coordonnées mènent à un point hors de la zone du titre du guide.",
    ["Makes a run step complete based on coordinates rather than zone name."] = "Fait terminer une étape de déplacement selon les coordonnées plutôt que le nom de zone.",
    ["Makes a run step complete based on coordinates rather than zone name. (CC)"] = "Fait terminer une étape de déplacement selon les coordonnées plutôt que le nom de zone. (CC)",
    ["Makes a run step complete based on a series of coordinates, followed in order."] = "Fait terminer une étape de déplacement selon une série de coordonnées, suivies dans l'ordre.",
    ["Makes a run step complete based on a series of coordinates, followed in order. (CS)"] = "Fait terminer une étape de déplacement selon une série de coordonnées, suivies dans l'ordre. (CS)",
    ["Do not complete based on coordinates. Just show the dots. (CN)"] = "Ne pas terminer selon les coordonnées. Afficher seulement les points. (CN)",
    -- Recorder step-editor descriptions, part 3.
    ["All guides are listed here, including those that come with the addon and those you have created using the recorder."] = "Tous les guides sont listés ici, y compris ceux fournis avec l'addon et ceux que vous avez créés avec l'enregistreur.",
    ["Details on how to complete this step of the guide. No more than one or two sentences, please."] = "Détails sur la façon de terminer cette étape du guide. Pas plus d'une ou deux phrases, s'il vous plaît.",
    ["Details on how to complete this step of the guide. No more than one or two sentences, please. Only leave blank for blatantly obvious steps."] = "Détails sur la façon de terminer cette étape du guide. Pas plus d'une ou deux phrases, s'il vous plaît. Ne laissez vide que pour les étapes évidentes.",
    ["Displayed if the user has the profession at the required skill level. Please enter in the form of 'Profession SkillLevel'."] = "Affiché si l'utilisateur possède le métier au niveau requis. Veuillez saisir au format « Métier Niveau ».",
    ["Enter coordinates for the step here, in the form '##.##,##.##'. Seperate multiple coordinates with semicolons (;)"] = "Saisissez ici les coordonnées de l'étape, au format '##.##,##.##'. Séparez plusieurs coordonnées par des points-virgules (;).",
    ["Full emitted guide lines for the current guide. The selected step is prefixed with >>."] = "Lignes de guide complètes pour le guide actuel. L'étape sélectionnée est précédée de >>.",
    ["If a particular quest must be active, list it's QID here. Seperate multiple actives with AND/OR (&^)"] = "Si une quête particulière doit être active, indiquez son QID ici. Séparez plusieurs quêtes actives par AND/OR (&^).",
    ["If it would be helpful to provide an easy way to target a named mob, enter the mob's name here. Use only for hard to find mobs."] = "S'il est utile de fournir un moyen simple de cibler un mob nommé, saisissez son nom ici. À n'utiliser que pour les mobs difficiles à trouver.",
    ["If the quest has a prerequisite, list it's QID here. Seperate multiple prerequisites with AND/OR (&^)"] = "Si la quête a un prérequis, indiquez son QID ici. Séparez plusieurs prérequis par AND/OR (&^).",
    ["If the step compeltes when you loot a certain number of items, put the number here."] = "Si l'étape se termine lorsque vous butinez un certain nombre d'objets, indiquez le nombre ici.",
    ["If the step completes based on a scenario stage or objective, put the stage (or stage and objective separated by a ;) here."] = "Si l'étape se termine selon une étape de scénario ou un objectif, indiquez l'étape (ou l'étape et l'objectif séparés par ;) ici.",
    ["If the step completes based on one or two quest objectives, not the whole quest, you can enter the quest objective here. Seperate multiple objectives with semicolons (;)"] = "Si l'étape se termine selon un ou deux objectifs de quête et non la quête entière, vous pouvez saisir l'objectif de quête ici. Séparez plusieurs objectifs par des points-virgules (;).",
    ["If the step completes when you loot an item, put it's ID here."] = "Si l'étape se termine lorsque vous butinez un objet, indiquez son ID ici.",
    ["If the step requires you to use an item, put it's ID here."] = "Si l'étape nécessite d'utiliser un objet, indiquez son ID ici.",
    ["If this quest is a Lead-In to another quest (meaning that other quest CAN be completed without this one, and doing so makes this quest no longer available), please list the quest it leads to's QID here."] = "Si cette quête est une introduction à une autre quête (l'autre quête PEUT être terminée sans celle-ci, ce qui rend cette quête indisponible), indiquez ici le QID de la quête vers laquelle elle mène.",
    ["Would you like to automatically populate some fields of the step based on a quest from your log? You can edit it afterwards."] = "Voulez-vous remplir automatiquement certains champs de l'étape à partir d'une quête de votre journal ? Vous pourrez les modifier ensuite.",
    -- Guide list column headers (WoWPro_Templates.lua).
    ["Zone"] = "Zone",
    ["Content"] = "Contenu",
    ["Author"] = "Auteur",
    ["Progress"] = "Progression",
}
